import React, { useState, useRef, useEffect, useCallback } from 'react';

const API_BASE = process.env.REACT_APP_API_URL || '';

const styles = {
  root: {
    minHeight: '100vh',
    background: '#09090b', // 优化：更深邃的现代暗色底
    color: '#f4f4f5', // 优化：高对比度文字色
    fontFamily: "'Inter', -apple-system, system-ui, sans-serif",
    display: 'flex',
    flexDirection: 'column',
  },
  header: {
    borderBottom: '1px solid #27272a', // 优化：更细腻的边框
    padding: '16px 24px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    background: '#09090b',
  },
  headerLeft: { display: 'flex', alignItems: 'center', gap: '12px' },
  logo: {
    width: '32px', height: '32px',
    background: 'linear-gradient(135deg, #60a5fa 0%, #818cf8 100%)', // 优化：亮蓝色渐变
    borderRadius: '8px',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontSize: '16px',
    boxShadow: '0 0 15px rgba(96, 165, 250, 0.2)',
  },
  headerTitle: { fontSize: '15px', fontWeight: '600', color: '#ffffff', letterSpacing: '-0.2px' },
  headerSub: { fontSize: '12px', color: '#71717a', marginTop: '1px' },
  sessionBadge: {
    fontSize: '11px', color: '#818cf8',
    background: 'rgba(129, 140, 248, 0.1)',
    border: '1px solid rgba(129, 140, 248, 0.2)',
    borderRadius: '20px', padding: '4px 10px',
    fontFamily: "'IBM Plex Mono', monospace",
  },
  main: { flex: 1, display: 'flex', maxWidth: '820px', width: '100%', margin: '0 auto', flexDirection: 'column', padding: '0 16px' },
  messageList: { flex: 1, padding: '24px 0', display: 'flex', flexDirection: 'column', gap: '20px', overflowY: 'auto' },
  empty: {
    flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
    gap: '12px', color: '#3f3f46', padding: '60px 0',
  },
  emptyIcon: { fontSize: '40px', opacity: 0.6 },
  emptyTitle: { fontSize: '16px', color: '#a1a1aa', fontWeight: '500' },
  emptyHints: { display: 'flex', flexWrap: 'wrap', gap: '8px', justifyContent: 'center', marginTop: '8px' },
  hint: {
    fontSize: '12px', color: '#94a3b8', background: '#18181b',
    border: '1px solid #27272a', borderRadius: '20px',
    padding: '6px 14px', cursor: 'pointer', transition: 'all 0.15s',
  },
  msgRow: (role) => ({
    display: 'flex',
    flexDirection: role === 'user' ? 'row-reverse' : 'row',
    gap: '10px', alignItems: 'flex-start',
  }),
  avatar: (role) => ({
    width: '28px', height: '28px', borderRadius: '50%', flexShrink: 0,
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontSize: '12px', fontWeight: '600', marginTop: '2px',
    background: role === 'user' ? '#27272a' : 'rgba(99, 102, 241, 0.2)',
    color: role === 'user' ? '#e4e4e7' : '#818cf8',
    border: role === 'user' ? '1px solid #3f3f46' : '1px solid rgba(129, 140, 248, 0.3)',
  }),
  bubble: (role) => ({
    maxWidth: '75%',
    background: role === 'user' ? '#1e1b4b' : '#18181b', // 优化：用户气泡更深邃，AI气泡深灰
    border: role === 'user' ? '1px solid #312e81' : '1px solid #27272a',
    borderRadius: role === 'user' ? '16px 4px 16px 16px' : '4px 16px 16px 16px',
    padding: '12px 16px',
    boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
  }),
  bubbleText: { fontSize: '14px', lineHeight: '1.65', color: '#e4e4e7', whiteSpace: 'pre-wrap' },
  stepsList: { marginTop: '10px', display: 'flex', flexWrap: 'wrap', gap: '6px' },
  step: {
    fontSize: '11px', fontFamily: "'IBM Plex Mono', monospace",
    color: '#a5b4fc', background: 'rgba(99, 102, 241, 0.1)',
    border: '1px solid rgba(99, 102, 241, 0.2)',
    borderRadius: '4px', padding: '2px 8px',
  },
  sourcesList: { marginTop: '10px' },
  sourceLabel: { fontSize: '11px', color: '#71717a', marginBottom: '4px', textTransform: 'uppercase', letterSpacing: '0.5px' },
  sourceLink: {
    display: 'block', fontSize: '12px', color: '#60a5fa',
    fontFamily: "'IBM Plex Mono', monospace",
    textDecoration: 'none', marginTop: '2px',
    overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
  },
  thinking: {
    fontSize: '13px', color: '#71717a', fontStyle: 'italic',
    display: 'flex', alignItems: 'center', gap: '8px',
  },
  dot: (i) => ({
    width: '5px', height: '5px', borderRadius: '50%',
    background: '#818cf8', display: 'inline-block',
    animation: `pulse 1.2s ease-in-out ${i * 0.2}s infinite`,
  }),
  inputArea: {
    padding: '16px 0 24px',
    borderTop: '1px solid #27272a',
  },
  inputRow: {
    display: 'flex', gap: '10px', alignItems: 'flex-end',
    background: '#18181b', border: '1px solid #27272a',
    borderRadius: '12px', padding: '10px 12px',
    transition: 'all 0.15s ease',
    boxShadow: '0 8px 32px rgba(0,0,0,0.2)',
  },
  textarea: {
    flex: 1, background: 'transparent', border: 'none', outline: 'none',
    color: '#fafafa', fontSize: '14px', lineHeight: '1.5',
    resize: 'none', fontFamily: "inherit",
    maxHeight: '120px', minHeight: '22px',
  },
  sendBtn: (disabled) => ({
    width: '32px', height: '32px', borderRadius: '8px', border: 'none',
    background: disabled ? '#27272a' : '#ffffff', // 优化：激活状态使用纯白，视觉冲击力强
    color: disabled ? '#52525b' : '#09090b',
    cursor: disabled ? 'not-allowed' : 'pointer',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontSize: '16px', flexShrink: 0, transition: 'all 0.15s',
  }),
  clearBtn: {
    fontSize: '12px', color: '#71717a', background: 'transparent',
    border: '1px solid #27272a', borderRadius: '6px',
    padding: '4px 10px', cursor: 'pointer', marginTop: '8px',
    transition: 'all 0.15s',
  },
};

const keyframes = `
@keyframes pulse {
  0%, 100% { opacity: 0.3; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.2); }
}
`;

function ThinkingDots() {
  return (
    <span style={styles.thinking}>
      <span style={styles.dot(0)} />
      <span style={styles.dot(1)} />
      <span style={styles.dot(2)} />
      thinking
    </span>
  );
}

function Message({ msg }) {
  const isUser = msg.role === 'user';
  return (
    <div style={styles.msgRow(msg.role)}>
      <div style={styles.avatar(msg.role)}>{isUser ? 'U' : 'AI'}</div>
      <div style={styles.bubble(msg.role)}>
        {msg.thinking ? (
          <ThinkingDots />
        ) : (
          <>
            <div style={styles.bubbleText}>{msg.content}</div>
            {msg.steps_taken && msg.steps_taken.length > 0 && (
              <div style={styles.stepsList}>
                {msg.steps_taken.map((s, i) => (
                  <span key={i} style={styles.step}>{s}</span>
                ))}
              </div>
            )}
            {msg.sources && msg.sources.length > 0 && (
              <div style={styles.sourcesList}>
                <div style={styles.sourceLabel}>Sources</div>
                {msg.sources.map((src, i) => (
                  <a key={i} href={src} target="_blank" rel="noreferrer" style={styles.sourceLink}>{src}</a>
                ))}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

const HINTS = [
  "What are recent advances in RAG for LLMs?",
  "Explain transformer attention mechanisms",
  "Find papers on RLHF for language models",
  "What is chain-of-thought prompting?",
];

function generateSessionId() {
  return 'sess_' + Math.random().toString(36).slice(2, 10);
}

export default function App() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [sessionId] = useState(generateSessionId);
  const bottomRef = useRef(null);
  const textareaRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const send = useCallback(async (queryText) => {
    const q = (queryText || input).trim();
    if (!q || loading) return;
    setInput('');

    setMessages(prev => [...prev, { role: 'user', content: q }]);
    setMessages(prev => [...prev, { role: 'assistant', thinking: true, content: '' }]);
    setLoading(true);

    try {
      const res = await fetch(`${API_BASE}/api/query`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ query: q, session_id: sessionId, top_k: 3 }),
      });
      const data = await res.json();
      setMessages(prev => [
        ...prev.slice(0, -1),
        {
          role: 'assistant',
          content: data.answer || data.detail || 'No response.',
          steps_taken: data.steps_taken || [],
          sources: data.sources || [],
        },
      ]);
    } catch (err) {
      setMessages(prev => [
        ...prev.slice(0, -1),
        { role: 'assistant', content: '⚠ Could not reach the backend. Make sure uvicorn is running on port 8000.' },
      ]);
    } finally {
      setLoading(false);
    }
  }, [input, loading, sessionId]);

  const handleKey = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      send();
    }
  };

  const clearHistory = async () => {
    try {
      await fetch(`${API_BASE}/api/history/${sessionId}`, { method: 'DELETE' });
    } catch {}
    setMessages([]);
  };

  return (
    <>
      <style>{keyframes}</style>
      <div style={styles.root}>
        <header style={styles.header}>
          <div style={styles.headerLeft}>
            <div style={styles.logo}>🔍</div>
            <div>
              <div style={styles.headerTitle}>AI Research Agent</div>
              <div style={styles.headerSub}>RAG · arXiv · GPT-4o-mini</div>
            </div>
          </div>
          <div style={styles.sessionBadge}>{sessionId}</div>
        </header>

        <main style={styles.main}>
          <div style={styles.messageList}>
            {messages.length === 0 ? (
              <div style={styles.empty}>
                <div style={styles.emptyIcon}>◎</div>
                <div style={styles.emptyTitle}>Ask about any research topic</div>
                <div style={styles.emptyHints}>
                  {HINTS.map((h, i) => (
                    <span key={i} style={styles.hint} onClick={() => send(h)}>{h}</span>
                  ))}
                </div>
              </div>
            ) : (
              messages.map((msg, i) => <Message key={i} msg={msg} />)
            )}
            <div ref={bottomRef} />
          </div>

          <div style={styles.inputArea}>
            <div style={styles.inputRow}>
              <textarea
                ref={textareaRef}
                style={styles.textarea}
                placeholder="Ask about a paper, topic, or concept..."
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyDown={handleKey}
                rows={1}
                disabled={loading}
              />
              <button style={styles.sendBtn(loading || !input.trim())} onClick={() => send()} disabled={loading || !input.trim()}>
                ↑
              </button>
            </div>
            {messages.length > 0 && (
              <button style={styles.clearBtn} onClick={clearHistory}>clear session</button>
            )}
          </div>
        </main>
      </div>
    </>
  );
}
